pm.test("Status HTTP é 200", () => {
    pm.response.to.have.status(200);
});

pm.test("success é true", () => {
    const body = pm.response.json();
    pm.expect(body.success).to.eql(true);
});

pm.test("status é UP", () => {
    const body = pm.response.json();
    pm.expect(body.status).to.eql("UP");
});

pm.test("timestamp existe", () => {
    const body = pm.response.json();
    pm.expect(body.timestamp).to.exist;
});

pm.test("uptime é um número", () => {
    const body = pm.response.json();
    pm.expect(body.uptime).to.be.a("number");
});
